"""Read a relative document from a configured directory."""
import posixpath

class ContainmentError(PermissionError):
    pass


def read_document(reader, root, relative):
    base = posixpath.normpath(root)
    target = posixpath.normpath(posixpath.join(base, relative))
    if posixpath.commonpath((base, target)) != base:
        raise ContainmentError("document is outside configured directory")
    return reader.read(target)

